// spec: .qa/e2e/specs/job-owner-questions.md §3 (3.1, 3.2) · cases JQ-3-1, JQ-3-2 · seed: tests/seed.talent.spec.ts
// Read-only: opens J-49 with ?questions=<thread of demo-talent-1>, reads the dialog, closes it. Nothing is sent.
import { test, expect, Page, ConsoleMessage } from '@playwright/test';
import path from 'path';
import { withLocale, Lang } from '../_helpers/i18n';

test.use({ storageState: path.join(__dirname, '../../../auth/talent.json') });

const J49 = '/collaborations/7e4ad713-60a0-4e68-9926-56e0ee667584';
const THREAD = '3a1added-bce8-477f-bb41-b3cbc09a1383'; // demo-talent-1's thread on J-49 (28.10)
const DIALOG_TITLE: Record<Lang, RegExp> = {
  he: /שאלות למנהל\/ת המשרה/,
  en: /Questions to the job manager/i,
  ru: /менеджер/i,
  ar: /مدير الوظيفة/,
};

/** Collects uncaught page errors and console errors. Resource 4xx/5xx lines («Failed to load resource») are ignored: the ticket is about uncaught JS errors. */
function collectErrors(page: Page) {
  const errors: string[] = [];
  page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
  page.on('console', (m: ConsoleMessage) => {
    if (m.type() === 'error' && !/Failed to load resource/i.test(m.text())) errors.push(`console.error: ${m.text()}`);
  });
  return errors;
}

async function expectQuestionsDialog(page: Page, lang: Lang) {
  const dlg = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: DIALOG_TITLE[lang] }) });
  await expect(dlg, 'questions dialog opens by itself from ?questions=').toBeVisible({ timeout: 30_000 });
  await expect(dlg.getByText('QA company post test').first()).toBeVisible();
  // the thread of this asker is shown (questions of 28.10 «QA-AUTO 2810 e0e6cc talent Q…»)
  await expect(dlg.getByText(/QA-AUTO/).first()).toBeVisible();
}

test.describe('Job owner questions — ?questions= link opens without React errors (#f44114)', () => {
  test('J-49 ?questions=<id>: questions dialog opens, 0 uncaught errors on 3 loads (he + en) @desktop @prod-safe #f44114', async ({ page }) => {
    test.setTimeout(180_000);
    const errors = collectErrors(page);
    const url = `${J49}?questions=${THREAD}`;

    for (let i = 1; i <= 3; i++) {
      if (i === 1) await page.goto(url);
      else await page.reload();
      await expectQuestionsDialog(page, 'he');
    }
    await page.goto(withLocale(url, 'en'));
    await expectQuestionsDialog(page, 'en');

    expect(errors, 'no uncaught errors (was «Minified React error #419» on every load)').toEqual([]);
    expect(errors.join('\n')).not.toMatch(/Minified React error|#419/);
  });

  test('Bell: the «answered your question» notification opens J-49 with the questions dialog, 0 uncaught errors @desktop @prod-safe #f44114', async ({ page }) => {
    test.setTimeout(120_000);
    const errors = collectErrors(page);
    await page.goto('/collaborations');
    await page.getByRole('button', { name: /התראות/ }).first().click();
    const item = page.getByText(/ענו על השאלה שלכם על המשרה „?QA company post test/).first();
    const found = await item.waitFor({ state: 'visible', timeout: 15_000 }).then(() => true, () => false);
    test.skip(!found, 'f44114: no «…ענו על השאלה שלכם על המשרה „QA company post test”» in the bell (aged out)');
    errors.length = 0; // count only the errors of the navigation from the bell
    await item.click();
    await page.waitForURL(/questions=/, { timeout: 30_000 });
    await expectQuestionsDialog(page, 'he');
    expect(errors, 'no uncaught errors after opening the job from the bell').toEqual([]);
  });
});
